import React, { useState } from 'react';
import axios from 'axios';
import QRCode from 'qrcode.react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

const UploadPage = () => {
  const [file, setFile] = useState(null);
  const [link, setLink] = useState('');
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [error, setError] = useState('');

  const handleUpload = async () => {
    if (!file) return alert('Please select a file first');

    setUploading(true);
    setError('');

    const formData = new FormData();
    formData.append('file', file);

    try {
      const { data } = await axios.post('/api/files/upload', formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        },
        onUploadProgress: progressEvent => {
          const percentCompleted = Math.round(
            (progressEvent.loaded * 100) / progressEvent.total
          );
          setUploadProgress(percentCompleted);
        }
      });

      setLink(data.file);
      setUploading(false);
    } catch (error) {
      console.error('Upload error:', error);
      setError(error.response?.data?.error || 'Error uploading file. Please try again.');
      setUploading(false);
    }
  };

  return (
    <div style={{ 
      padding: '20px',
      textAlign: 'center',
      maxWidth: '600px',
      margin: '0 auto'
    }}>
      <h2 style={{ color: '#ff7e5f', marginBottom: '16px' }}>Quanta-Share</h2>

      <label style={{ 
        display: 'block', 
        padding: '40px', 
        border: '2px dashed #ccc', 
        borderRadius: '8px', 
        cursor: 'pointer', 
        transition: 'border-color 0.3s ease',
        backgroundColor: file ? '#f9f9f9' : 'transparent'
      }}>
        <input 
          type="file" 
          onChange={(e) => setFile(e.target.files[0])} 
          style={{ display: 'none' }} 
        />
        <div style={{ fontSize: '16px', color: '#555' }}>
          {file ? (
            <>
              <div style={{ marginBottom: '10px' }}>Selected file: {file.name}</div>
              <div>Size: {(file.size / (1024 * 1024)).toFixed(2)} MB</div>
            </>
          ) : (
            <>
              Click to browse or drag files here to start sharing
              <br />
              <span style={{ fontSize: '12px', color: '#999' }}>(Max file size: 100MB)</span>
            </>
          )}
        </div>
      </label>

      {uploading && (
        <div style={{ 
          height: '6px', 
          backgroundColor: '#f0f0f0', 
          borderRadius: '3px', 
          margin: '16px 0', 
          overflow: 'hidden' 
        }}>
          <div style={{ 
            height: '100%', 
            width: `${uploadProgress}%`, 
            backgroundColor: '#ff7e5f', 
            transition: 'width 0.3s ease' 
          }}></div>
        </div>
      )}

      {error && (
        <div style={{ color: '#e74c3c', margin: '10px 0', fontSize: '14px' }}>
          {error}
        </div>
      )}

      <button 
        onClick={handleUpload} 
        disabled={!file || uploading}
        style={{ 
          background: !file || uploading ? '#ccc' : '#ff7e5f', 
          color: '#fff', 
          padding: '12px 24px', 
          marginTop: '16px', 
          borderRadius: '8px', 
          border: 'none', 
          cursor: !file || uploading ? 'not-allowed' : 'pointer', 
          transition: 'background 0.3s ease' 
        }}
      >
        {uploading ? 'Uploading...' : 'Upload & Share'}
      </button>

      {link && (
        <div style={{ marginTop: '20px', textAlign: 'center' }}>
          <p style={{ marginBottom: '10px', color: '#333' }}>Share this link:</p>
          <a 
            href={link} 
            target="_blank" 
            rel="noopener noreferrer" 
            style={{ 
              color: '#ff7e5f', 
              textDecoration: 'none', 
              fontSize: '14px',
              wordBreak: 'break-all',
              display: 'block',
              padding: '10px',
              backgroundColor: '#f9f9f9',
              borderRadius: '4px',
              marginBottom: '15px'
            }}
          >
            {link}
          </a>
          <div style={{ marginTop: '10px' }}>
            <p style={{ marginBottom: '10px', color: '#333' }}>Or scan this QR code:</p>
            <div style={{ display: 'inline-block', background: 'white', padding: '10px', borderRadius: '4px' }}>
              <QRCode value={link} size={150} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const FileDetailsPage = () => {
  return (
    <div style={{ padding: '20px', textAlign: 'center' }}>
      <h2 style={{ color: '#ff7e5f' }}>File Details</h2>
      <p>This page will display file details</p>
    </div>
  );
};

const Header = () => {
  return (
    <header style={{ 
      background: 'linear-gradient(to right, #ff7e5f, #feb47b)',
      color: 'white',
      padding: '15px 20px',
      textAlign: 'center'
    }}>
      <h1 style={{ margin: 0, fontSize: '24px' }}>Quanta-Share</h1>
      <p style={{ margin: '5px 0 0', fontSize: '14px' }}>Share files securely</p>
    </header>
  );
};

const Footer = () => {
  return (
    <footer style={{ 
      textAlign: 'center',
      padding: '15px',
      marginTop: '20px',
      borderTop: '1px solid #eee',
      color: '#666',
      fontSize: '14px'
    }}>
      <p style={{ margin: 0 }}>© 2023 Quanta-Share. All rights reserved.</p>
    </footer>
  );
};

function App() {
  return (
    <Router>
      <div style={{ 
        fontFamily: 'Poppins, sans-serif',
        minHeight: '100vh',
        display: 'flex',
        flexDirection: 'column',
        background: '#f9f9f9'
      }}>
        <Header />
        <main style={{ 
          flex: 1,
          padding: '20px',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'flex-start'
        }}>
          <Routes>
            <Route path="/" element={<UploadPage />} />
            <Route path="/file/:uuid" element={<FileDetailsPage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
